DROP TABLE IF EXISTS `lead`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lead` (
  `Lead_Id` int NOT NULL AUTO_INCREMENT,
  `Lead_Name` varchar(100) DEFAULT NULL,
  `Lead_Type` int DEFAULT '0',
  `Vertical` int DEFAULT NULL,
  `Vertical_Name` varchar(100) DEFAULT NULL,
  `Deal_Type_Id` int DEFAULT NULL,
  `Deal_Type_Name` varchar(255) DEFAULT NULL,
  `Address` varchar(1000) DEFAULT NULL,
  `State` int DEFAULT NULL,
  `State_Name` varchar(100) DEFAULT NULL,
  `District` int DEFAULT NULL,
  `District_Name` varchar(100) DEFAULT NULL,
  `Company_Size_Id` int DEFAULT '0',
  `Company_Size_Name` varchar(100) DEFAULT NULL,
  `Source` int DEFAULT NULL,
  `Source_Name` varchar(100) DEFAULT NULL,
  `POC_Full_Name` varchar(255) DEFAULT NULL,
  `POC_Designation_Id` int DEFAULT NULL,
  `POC_Designation` varchar(255) DEFAULT NULL,
  `POC_Direct_Mobile` varchar(50) DEFAULT NULL,
  `POC_Email` varchar(255) DEFAULT NULL,
  `POC_State_Id` int DEFAULT NULL,
  `POC_State` varchar(100) DEFAULT NULL,
  `POC_Location_Id` int DEFAULT NULL,
  `POC_Loc` varchar(100) DEFAULT NULL,
  `POC_Work_Phone` varchar(50) DEFAULT NULL,
  `POC_Office_Type` varchar(100) DEFAULT NULL,
  `Name_Captured` tinyint(1) DEFAULT '0',
  `Number_Captured` tinyint(1) DEFAULT '0',
  `Email_Captured` tinyint(1) DEFAULT '0',
  `Enquiry_For` varchar(500) DEFAULT NULL,
  `Enquiry_For_Note` varchar(1000) DEFAULT NULL,
  `Market_Study_Systems` text,
  `Lead_Priority` varchar(50) DEFAULT 'Medium',
  `PipelineStage_Id` int DEFAULT '0',
  `Current_Pipeline_Stage` varchar(100) DEFAULT NULL,
  `Stage_Type` tinyint(1) NOT NULL DEFAULT '0',
  `Followup_Required` tinyint(1) DEFAULT '1',
  `Color` varchar(20) DEFAULT '#3b82f6',
  `Pulse_Id` int DEFAULT '0',
  `Pulse` varchar(100) DEFAULT NULL,
  `isGhosting` tinyint(1) DEFAULT '0',
  `sale_won` tinyint(1) DEFAULT '0',
  `sale_won_date` datetime DEFAULT NULL,
  `sale_won_by` int DEFAULT NULL,
  `sale_lost` tinyint(1) DEFAULT '0',
  `sale_lost_date` datetime DEFAULT NULL,
  `sale_lost_by` int DEFAULT NULL,
  `Branch_Id` int DEFAULT NULL,
  `Branch_Name` varchar(100) DEFAULT NULL,
  `Department_Id` int DEFAULT NULL,
  `Department_Name` varchar(100) DEFAULT NULL,
  `Staff_Id` int DEFAULT NULL,
  `Staff_Name` varchar(100) DEFAULT NULL,
  `Target_Stage_Id` int DEFAULT NULL,
  `Target_Stage_Name` varchar(100) DEFAULT NULL,
  `Next_FollowUp_Date` date DEFAULT NULL,
  `Remarks` varchar(1000) DEFAULT NULL,
  `Workflow_Id` int DEFAULT '0',
  `Workflow` varchar(100) DEFAULT NULL,
  `Workflow_Start_Status` tinyint(1) DEFAULT '0',
  `Entry_Date` datetime DEFAULT CURRENT_TIMESTAMP,
  `Status_Id` int DEFAULT NULL,
  `Status_Name` varchar(100) DEFAULT NULL,
  `Next_Call_Action` tinyint(1) DEFAULT '0',
  `Review` varchar(1000) DEFAULT NULL,
  `Rate` varchar(100) DEFAULT NULL,
  `Online_Meeting_Count` int DEFAULT '0',
  `Offline_Meeting_Count` int DEFAULT '0',
  `Quote_Sent_Count` int DEFAULT '0',
  `Lost_Reason_Id` int DEFAULT NULL,
  `Primary_Issue_Id` int DEFAULT NULL,
  `Competitor` varchar(255) DEFAULT '',
  `Lost_Reason` varchar(255) DEFAULT NULL,
  `Lost_Primary_Issue` varchar(255) DEFAULT NULL,
  `Lost_Competitor_Name` varchar(255) DEFAULT NULL,
  `Lost_Competitor_Price` decimal(18,2) DEFAULT NULL,
  `Lost_Was_Price_Issue` tinyint(1) DEFAULT NULL,
  `Lost_Was_Solution_Issue` tinyint(1) DEFAULT NULL,
  `Lost_Quote_Only_Comparison` tinyint(1) DEFAULT NULL,
  `Lost_Reopen_Possibility` varchar(20) DEFAULT NULL,
  `Lost_Expected_Reconnect_Date` date DEFAULT NULL,
  `Lost_Remarks` text,
  PRIMARY KEY (`Lead_Id`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
