--
-- Table structure for table `lead_activity_log`
--

DROP TABLE IF EXISTS `lead_activity_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lead_activity_log` (
  `LeadActivityLog_Id` int NOT NULL AUTO_INCREMENT,
  `Activity_Date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Lead_Id` int NOT NULL,
  `Lead_Name` varchar(255) DEFAULT NULL,
  `Deal_Type` varchar(50) DEFAULT NULL,
  `Old_Value` text,
  `New_Value` text,
  `Action_Taken` varchar(50) NOT NULL,
  `Activity_Title` varchar(255) NOT NULL,
  `Outcome` varchar(255) DEFAULT NULL,
  `Next_Follow_Up` date DEFAULT NULL,
  `Notes` text,
  `Branch_Id` int DEFAULT NULL,
  `Branch_Name` varchar(255) DEFAULT NULL,
  `Department_Id` int DEFAULT NULL,
  `Department_Name` varchar(255) DEFAULT NULL,
  `Staff_Id` int DEFAULT NULL,
  `Staff_Name` varchar(255) DEFAULT NULL,
  `User_Id` int DEFAULT NULL,
  `Won_Lost_Status` tinyint DEFAULT '0',
  PRIMARY KEY (`LeadActivityLog_Id`),
  KEY `idx_lead_activity_log_lead` (`Lead_Id`),
  KEY `idx_branch_id` (`Branch_Id`),
